import{_ as t,o,c as a,a2 as r}from"./chunks/framework.C8822HRV.js";const u=JSON.parse('{"title":"Why sdd exists","description":"Why local Spec-Driven Development beats pure vibe coding and heavy enterprise SDD. sdd pairs a CLI process spine with your AI coding agent — portable, progressive, no IDE lock-in.","frontmatter":{"title":"Why sdd exists","description":"Why local Spec-Driven Development beats pure vibe coding and heavy enterprise SDD. sdd pairs a CLI process spine with your AI coding agent — portable, progressive, no IDE lock-in.","head":[["meta",{"property":"og:title","content":"Why sdd exists · sdd"}],["meta",{"property":"og:description","content":"Why local Spec-Driven Development beats pure vibe coding and heavy enterprise SDD. sdd pairs a CLI process spine with your AI coding agent — portable, progressive, no IDE lock-in."}],["meta",{"property":"og:url","content":"https://harsha09.github.io/spec-driven-development/concepts/why-sdd/"}],["meta",{"property":"og:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["meta",{"name":"twitter:title","content":"Why sdd exists · sdd"}],["meta",{"name":"twitter:description","content":"Why local Spec-Driven Development beats pure vibe coding and heavy enterprise SDD. sdd pairs a CLI process spine with your AI coding agent — portable, progressive, no IDE lock-in."}],["meta",{"name":"twitter:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["link",{"rel":"canonical","href":"https://harsha09.github.io/spec-driven-development/concepts/why-sdd/"}]]},"headers":[],"relativePath":"concepts/why-sdd.md","filePath":"concepts/why-sdd.md","lastUpdated":1785895617000}'),i={name:"concepts/why-sdd.md"};function s(n,e,d,l,h,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="why-sdd-exists" tabindex="-1">Why sdd exists <a class="header-anchor" href="#why-sdd-exists" aria-label="Permalink to &quot;Why sdd exists&quot;">​</a></h1><blockquote><p>AI needs a little structure. People need that structure to stay light.</p></blockquote><h2 id="two-problems-you-ve-probably-felt" tabindex="-1">Two problems you’ve probably felt <a class="header-anchor" href="#two-problems-you-ve-probably-felt" aria-label="Permalink to &quot;Two problems you’ve probably felt&quot;">​</a></h2><p><strong>Chat-only coding</strong> ships fast. Then the <em>why</em> is gone — buried in threads, lost context windows, or a PR that only shows the diff.</p><p><strong>Heavy process tools</strong> keep the trail — and often feel like a second job for a three-line fix.</p><p>You bounce between “move fast and forget” and “process theater.” Neither fits a world where the AI can draft a thousand lines before you finish naming the ticket.</p><h2 id="the-simple-bet" tabindex="-1">The simple bet <a class="header-anchor" href="#the-simple-bet" aria-label="Permalink to &quot;The simple bet&quot;">​</a></h2><p><strong>The AI writes. <code>sdd</code> keeps the plan and progress in git.</strong></p><p>Longer problem write-up: <a href="./keep-ai-coding-in-git">Keep AI coding decisions in git</a>.</p><ul><li>Notes live <strong>in your repo</strong>, next to the code — not only in a cloud product.</li><li>Small work stays short; bigger work can go deeper.</li><li><strong>One</strong> short playbook, not a pile of plugins.</li><li>Pick <strong>one</strong> AI at setup. Use any editor.</li></ul><h2 id="what-we-won-t-force-on-you" tabindex="-1">What we won’t force on you <a class="header-anchor" href="#what-we-won-t-force-on-you" aria-label="Permalink to &quot;What we won’t force on you&quot;">​</a></h2><ul><li>A required IDE extension</li><li>A hosted suite as the only source of truth</li><li>Mandatory archive folders</li></ul><h2 id="who-it-s-for" tabindex="-1">Who it’s for <a class="header-anchor" href="#who-it-s-for" aria-label="Permalink to &quot;Who it’s for&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You</th><th>Why it helps</th></tr></thead><tbody><tr><td>Solo / small team</td><td>A bit of structure without ceremony</td></tr><tr><td>Product team</td><td>Same trail in every PR</td></tr><tr><td>Enterprise</td><td>Reviewable steps next to the code</td></tr></tbody></table><h2 id="try-before-you-buy-the-idea" tabindex="-1">Try before you buy the idea <a class="header-anchor" href="#try-before-you-buy-the-idea" aria-label="Permalink to &quot;Try before you buy the idea&quot;">​</a></h2><p><strong>→ <a href="./../tutorials/first-change">Start in 10 minutes</a></strong></p><p>Then: <a href="./../guides/everyday-loop">Everyday loop</a> · <a href="./../guides/greenfield">New product</a></p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./what-is-sdd">What is sdd</a></li><li><a href="./change-packs">Change packs &amp; memory</a></li></ul>',19)])])}const y=t(i,[["render",s]]);export{u as __pageData,y as default};
